+		animation-play-state: paused;
+	}
+
+	.star:hover::before {
+		width: calc(var(--beam-len) * 2.5);
+	}
+
+	.star:hover::after {
+		height: calc(var(--beam-len) * 2.5);
+	}
+
+	.star:hover .star-tooltip {
+		opacity: 1;
+		transform: translateX(-50%) translateY(0);
+	}
+
+	.star::before {
+		content: "";
+		position: absolute;
+		top: 50%;
+		left: 50%;
+		transform: translate(-50%, -50%);
+		width: var(--beam-len);
+		height: var(--beam-w);
+		transition:
+			width 0.3s ease,
+			height 0.3s ease;
+		background: linear-gradient(
+			90deg,
+			transparent 0%,
+			color-mix(in srgb, var(--color) 15%, transparent) 20%,
+			color-mix(in srgb, var(--color) 50%, transparent) 40%,
+			#fff 50%,
+			color-mix(in srgb, var(--color) 50%, transparent) 60%,
+			color-mix(in srgb, var(--color) 15%, transparent) 80%,
+			transparent 100%
+		);
+		pointer-events: none;
+	}
+
+	.star::after {
+		content: "";
+		position: absolute;
+		top: 50%;
+		left: 50%;
+		transform: translate(-50%, -50%);
+		height: var(--beam-len);
+		width: var(--beam-w);
+		transition:
+			width 0.3s ease,
+			height 0.3s ease;
+		background: linear-gradient(
+			180deg,
+			transparent 0%,
+			color-mix(in srgb, var(--color) 15%, transparent) 20%,
+			color-mix(in srgb, var(--color) 50%, transparent) 40%,
+			#fff 50%,
+			color-mix(in srgb, var(--color) 50%, transparent) 60%,
+			color-mix(in srgb, var(--color) 15%, transparent) 80%,
+			transparent 100%
+		);
+		pointer-events: none;
+	}
+
+	@keyframes star-pulse {
+		0%,
+		100% {
+			opacity: var(--glow);
+		}
+		50% {
+			opacity: calc(var(--glow) * 0.8);
+		}
+	}
+</style>

